var MARKER = /shortcut:\s*(.+?)(?:\s+trigger:\s*(\S.*?))?\s*(?:\*\/|-->)?\s*$/i;
var markerItems = (runtime, paths) => linesOf3(
  gitAt(runtime, paths.root).out([
    "grep",
    "-n",
    "-I",
    "-i",
    "-E",
    "-e",
    "(//|#|/\\*|<!--|--) *shortcut:",
    "--",
    ".",
    ":(exclude)docs/plan",
    ":(exclude).finitemonkey"
  ])
).flatMap((line14) => {
  const at9 = /^(.+?):(\d+):(.*)$/.exec(line14);
  const match = at9 === null ? null : MARKER.exec(at9[3] ?? "");
  if (at9 === null || match?.[1] === void 0) return [];
  return [
    {
      source: "marker",
      what: match[1],
      ...match[2] === void 0 ? {} : { trigger: match[2] },
      where: `${at9[1] ?? ""}:${at9[2] ?? ""}`
    }
  ];
});
var openItems = (runtime, paths) => {
  const active = readState(runtime, paths).active;
  if (active === void 0) return [];
  const text45 = runtime.readText(paths.task(active));
  const parsed = text45.ok ? parseContract(active, text45.value) : void 0;
  return parsed?.ok === true ? (parsed.value.shortcuts ?? []).map((item2) => ({ source: "open", task: active, ...item2 })) : [];
};
var listDebt = (runtime, paths) => {
  const closed = readShortcutRows(runtime, paths).map((row4) => ({
    source: "closed",
    task: row4.task,
    what: row4.what,
    ...row4.ceiling === void 0 ? {} : { ceiling: row4.ceiling },
    ...row4.trigger === void 0 ? {} : { trigger: row4.trigger },
    ...row4.where === void 0 ? {} : { where: row4.where }
  }));
  const markers = defaultOn(runtime, paths.root, "no-comments") ? [] : markerItems(runtime, paths);
  return [...closed, ...openItems(runtime, paths), ...markers].map((item2) => {
    const result2 = evaluateTrigger(runtime, paths.root, item2.trigger);
    return { ...item2, state: result2.state, detail: result2.detail };
  });
};

// src/commands/debt.ts
var DEBT_SCHEMA = "finitemonkey/debt@1";
var debtCommand = {
  path: ["debt"],
  summaryKey: "command.debt.summary",
  usage: "finitemonkey debt",
  status: "ready",
  run: (ctx) => {
    const repo = repoOf(ctx);
    if (repo === void 0) return Promise.resolve(failureFrom(ctx.t, notRepository(ctx.cwd)));
    const items2 = listDebt(ctx.runtime, fmPaths(repo.root));
    const lines11 = items2.map(
      (item2) => ctx.t("debt.row", {
        state: item2.state,
        what: item2.what,
        task: item2.task ?? "-",
        where: item2.where ?? "-",
        detail: item2.detail === "" ? "-" : item2.detail
      })
    );
    return Promise.resolve(
      success({ schema: DEBT_SCHEMA, items: items2 }, [ctx.t("debt.title", { count: items2.length }), ...lines11])
    );
  }
};

